typedef uint64_t tuff_plugin_types_event_kinds_t;

#define TUFF_PLUGIN_TYPES_EVENT_KINDS_JOIN (1 << 0)
#define TUFF_PLUGIN_TYPES_EVENT_KINDS_LEAVE (1 << 1)
#define TUFF_PLUGIN_TYPES_EVENT_KINDS_CHAT (1 << 2)
#define TUFF_PLUGIN_TYPES_EVENT_KINDS_BLOCK_BREAK (1 << 3)
#define TUFF_PLUGIN_TYPES_EVENT_KINDS_BLOCK_PLACE (1 << 4)
#define TUFF_PLUGIN_TYPES_EVENT_KINDS_LEFT_CLICK (1 << 5)
#define TUFF_PLUGIN_TYPES_EVENT_KINDS_RIGHT_CLICK (1 << 6)
#define TUFF_PLUGIN_TYPES_EVENT_KINDS_ENTITY_SPAWN (1 << 7)
#define TUFF_PLUGIN_TYPES_EVENT_KINDS_ENTITY_DEATH (1 << 8)
#define TUFF_PLUGIN_TYPES_EVENT_KINDS_ENTITY_DAMAGE (1 << 9)
#define TUFF_PLUGIN_TYPES_EVENT_KINDS_PLAYER_HURT (1 << 10)
#define TUFF_PLUGIN_TYPES_EVENT_KINDS_PLAYER_DEATH (1 << 11)
#define TUFF_PLUGIN_TYPES_EVENT_KINDS_INSIDE_BLOCK (1 << 12)
#define TUFF_PLUGIN_TYPES_EVENT_KINDS_CONFIG_CHANGE (1 << 13)
// A login that passed the ban, whitelist and player-count checks,
// before the player joins. The plugin may refuse it with
// `refuse-login` while handling the event.
#define TUFF_PLUGIN_TYPES_EVENT_KINDS_LOGIN (1 << 14)
// A player clicked a slot of a plugin menu (`open-menu`).
#define TUFF_PLUGIN_TYPES_EVENT_KINDS_MENU_CLICK (1 << 15)
// A plugin menu a player had open closed.
#define TUFF_PLUGIN_TYPES_EVENT_KINDS_MENU_CLOSE (1 << 16)
// A player right-clicked a non-player entity.
#define TUFF_PLUGIN_TYPES_EVENT_KINDS_ENTITY_INTERACT (1 << 17)
#define TUFF_PLUGIN_TYPES_EVENT_KINDS_USE_ITEM (1 << 18)
#define TUFF_PLUGIN_TYPES_EVENT_KINDS_PROJECTILE_HIT (1 << 19)
// A player attacked a non-player entity.
#define TUFF_PLUGIN_TYPES_EVENT_KINDS_PLAYER_ATTACK (1 << 20)
// A hit on a player a damage filter matched.
#define TUFF_PLUGIN_TYPES_EVENT_KINDS_DAMAGE_FILTERED (1 << 21)
// A player dropped an item (Q, or Ctrl+Q for the stack).
#define TUFF_PLUGIN_TYPES_EVENT_KINDS_ITEM_DROP (1 << 22)
// A player picked up a dropped item.
#define TUFF_PLUGIN_TYPES_EVENT_KINDS_ITEM_PICKUP (1 << 23)
// A player swapped the items of their hands (F).
#define TUFF_PLUGIN_TYPES_EVENT_KINDS_ITEM_SWAP (1 << 24)
// A player took the result of a crafting grid.
#define TUFF_PLUGIN_TYPES_EVENT_KINDS_ITEM_CRAFT (1 << 25)
// A `take-items` call finished removing items from a player.
#define TUFF_PLUGIN_TYPES_EVENT_KINDS_ITEMS_TAKEN (1 << 26)
// An explosion found blocks to destroy.
#define TUFF_PLUGIN_TYPES_EVENT_KINDS_EXPLOSION (1 << 27)
// A player clicked or dragged in a window (inventory block).
#define TUFF_PLUGIN_TYPES_EVENT_KINDS_INVENTORY_CLICK (1 << 28)
// A container window opened for a player.
#define TUFF_PLUGIN_TYPES_EVENT_KINDS_INVENTORY_OPEN (1 << 29)
// A player's container window closed.
#define TUFF_PLUGIN_TYPES_EVENT_KINDS_INVENTORY_CLOSE (1 << 30)
// Respawns, sneaking, game mode, food level and dimension
// changes of players.
#define TUFF_PLUGIN_TYPES_EVENT_KINDS_PLAYER_STATE (1ULL << 31)
// A client sent a custom payload on a channel the plugin
// registered with `register-channel`.
#define TUFF_PLUGIN_TYPES_EVENT_KINDS_PAYLOAD (1ULL << 32)

