typedef uint8_t tuff_plugin_types_click_kind_t;

// Starting to break a block.
#define TUFF_PLUGIN_TYPES_CLICK_KIND_LEFT 0
// Using the held item on a block.
#define TUFF_PLUGIN_TYPES_CLICK_KIND_RIGHT 1
// Using the held item in the air; the filter's `block` must be
// none.
#define TUFF_PLUGIN_TYPES_CLICK_KIND_AIR 2

