typedef struct {
  bool is_some;
  int16_t val;
} plugin_option_s16_t;

typedef struct {
  bool is_some;
  tuff_plugin_types_inventory_click_kind_t val;
} tuff_plugin_types_option_inventory_click_kind_t;

// Window clicks the server cancels itself and reports as
// `inventory-click` events. Every field narrows the match; none
// matches every click. Window 0 is the player inventory, container
// `player`; slots are the window's own numbering.
typedef struct tuff_plugin_types_inventory_filter_t {
  // `player`, `chest`, `shulker_box`, `hopper`, `dispenser`,
  // `crafting_table`, `stonecutter`, `cartography_table`,
  // `smithing_table`, `furnace`, `blast_furnace`, `smoker`,
  // `brewing_stand`, `merchant`, `crafter`, `lectern` or `mount`.
  plugin_option_string_t   container;
  plugin_option_s16_t   first_slot;
  plugin_option_s16_t   last_slot;
  // An item id the clicked slot or the cursor stack must be.
  plugin_option_string_t   item;
  tuff_plugin_types_option_inventory_click_kind_t   click;
} tuff_plugin_types_inventory_filter_t;

// A click in a window. `cancelled` is true when a filter matched.
typedef struct tuff_plugin_types_inventory_click_t {
  tuff_plugin_types_player_t   player;
  plugin_string_t   container;
  int16_t   slot;
  tuff_plugin_types_inventory_click_kind_t   click;
  // The stack in the clicked slot, else the cursor stack; empty when
  // there is none.
  plugin_string_t   item;
  uint8_t   count;
  bool   cancelled;
} tuff_plugin_types_inventory_click_t;

// A container window opening or closing for a player. Neither can be
// cancelled.
typedef struct tuff_plugin_types_inventory_window_t {
  tuff_plugin_types_player_t   player;
  plugin_string_t   container;
} tuff_plugin_types_inventory_window_t;

// An item action by a player, cancelled or not.
typedef struct tuff_plugin_types_item_action_t {
  tuff_plugin_types_player_t   player;
  plugin_string_t   item;
  uint8_t   count;
  plugin_string_t   dimension;
} tuff_plugin_types_item_action_t;

// What a `take-items` call removed once its queued edit ran. A call
// that skipped (a failed all-or-nothing take) reports `removed` 0.
typedef struct tuff_plugin_types_items_taken_t {
  tuff_plugin_types_player_t   player;
  plugin_string_t   item;
  uint32_t   requested;
  uint32_t   removed;
  plugin_string_t   dimension;
} tuff_plugin_types_items_taken_t;

