// Drop it; the optional text is shown to the sender.
#define TUFF_PLUGIN_TYPES_LINE_ACTION_CANCEL 0
// Run or send this text instead. For a command filter the
// matched leading words are replaced and the rest kept; for a
// chat filter the whole message is replaced.
#define TUFF_PLUGIN_TYPES_LINE_ACTION_REWRITE 1

// A command line (without its slash) the server cancels or rewrites
// before any command runs.
typedef struct tuff_plugin_types_command_filter_t {
  // Leading words to match, case-insensitively, on word borders
  // (`give` matches `give Steve stone` but not `giveall`).
  plugin_string_t   prefix;
  tuff_plugin_types_line_action_t   action;
} tuff_plugin_types_command_filter_t;

// A chat message the server cancels or rewrites before it is sent.
// Both conditions given must hold; none matches every message.
typedef struct tuff_plugin_types_chat_filter_t {
  // The message must start with this, case-insensitively.
  plugin_option_string_t   prefix;
  // The message must contain this, case-insensitively.
  plugin_option_string_t   contains;
  tuff_plugin_types_line_action_t   action;
} tuff_plugin_types_chat_filter_t;

// Which right-clicks on non-player entities the server cancels (the
// villager's trade screen, a mount) instead of letting vanilla act;
// they are reported as `entity-interact` events either way once the
// plugin subscribes.
typedef struct tuff_plugin_types_entity_filter_t {
  // An entity type id; none for any.
  plugin_option_string_t   kind;
  // A scoreboard tag the entity must have (`Tags` in its data); none
  // for any.
  plugin_option_string_t   tag;
  // The area is tested against the entity's position.
  // Narrows the match to a dimension or area, or exempts players.
  tuff_plugin_types_filter_scope_t   scope;
} tuff_plugin_types_entity_filter_t;

// A right-click on a non-player entity, in the main hand.
typedef struct tuff_plugin_types_entity_interact_t {
  tuff_plugin_types_player_t   player;
  tuff_plugin_types_uuid_t   entity;
  // Its type, like `minecraft:villager`.
  plugin_string_t   kind;
  // The custom entity id when the target is a custom entity or one
  // of its interaction parts (then `entity` and `kind` are the
  // owner's).
  plugin_option_string_t   custom;
  // Whether a filter cancelled the vanilla interaction.
  bool   cancelled;
} tuff_plugin_types_entity_interact_t;

// Which melee attacks on entities, players included, the server cancels. Every
// field that is set must match. Matching attacks are reported as
// `player-attack` events once the plugin subscribes.
typedef struct tuff_plugin_types_attack_filter_t {
  // The victim's entity type id; none for any.
  plugin_option_string_t   kind;
  // A scoreboard tag the victim must have; none for any.
  plugin_option_string_t   tag;
  // The attacker's held item id; none for any.
  plugin_option_string_t   held_item;
  // Only attacks by this player; none for any.
  tuff_plugin_types_option_uuid_t   attacker;
  // A dimension key the victim must be in; none for any.
  plugin_option_string_t   dimension;
  // A box (two corners) the victim must be inside; none for anywhere.
  tuff_plugin_types_option_tuple2_vec3_vec3_t   area;
} tuff_plugin_types_attack_filter_t;

// A melee attack by a player on an entity or another player.
typedef struct tuff_plugin_types_player_attack_t {
  tuff_plugin_types_player_t   player;
  tuff_plugin_types_uuid_t   victim;
  // The victim's type, like `minecraft:zombie`.
  plugin_string_t   kind;
  // The custom entity id when the victim is a custom entity or one
  // of its interaction parts (then `victim` and `kind` are the
  // owner's).
  plugin_option_string_t   custom;
  // Whether a filter cancelled the attack.
  bool   cancelled;
} tuff_plugin_types_player_attack_t;

// Which damage to players and mobs the server cancels or scales
// without running guest code (the `damage-filtered` event
// reports both). Every field that is set must match; the first
// matching filter acts. Matches are reported as `damage-filtered`.
typedef struct tuff_plugin_types_damage_filter_t {
  // Only this victim (a player or a mob); none for any.
  tuff_plugin_types_option_uuid_t   victim;
  // Damage type ids (`minecraft:fall`, `minecraft:out_of_world`,
  // `minecraft:on_fire`, `minecraft:arrow`); empty for any cause.
  plugin_list_string_t   causes;
  // Only damage dealt by this entity; none for any.
  tuff_plugin_types_option_uuid_t   attacker;
  // Only damage dealt by this entity type; none for any.
  plugin_option_string_t   attacker_kind;
  // A dimension key the victim must be in; none for any.
  plugin_option_string_t   dimension;
  // A box (two corners) the victim must be inside; none for anywhere.
  tuff_plugin_types_option_tuple2_vec3_vec3_t   area;
  // Multiplies the damage: 0 cancels the hit entirely (no knockback
  // or hurt animation), 0.5 halves it. Not below 0.
  float   scale;
} tuff_plugin_types_damage_filter_t;

// A non-player entity hit by a damage filter: its uuid and entity
// type id such as `minecraft:cow`.
typedef struct tuff_plugin_types_damaged_entity_t {
  tuff_plugin_types_uuid_t   uuid;
  plugin_string_t   kind;
} tuff_plugin_types_damaged_entity_t;

// Who a damage filter matched.
typedef struct tuff_plugin_types_damage_victim_t {
  uint8_t tag;
  union {
    tuff_plugin_types_player_t     player;
    tuff_plugin_types_damaged_entity_t     entity;
  } val;
} tuff_plugin_types_damage_victim_t;

#define TUFF_PLUGIN_TYPES_DAMAGE_VICTIM_PLAYER 0
#define TUFF_PLUGIN_TYPES_DAMAGE_VICTIM_ENTITY 1

// A hit that a damage filter matched.
typedef struct tuff_plugin_types_damage_filtered_t {
  tuff_plugin_types_damage_victim_t   victim;
  plugin_string_t   damage_type;
  tuff_plugin_types_option_uuid_t   attacker;
  // The matching filter's scale.
  float   scale;
} tuff_plugin_types_damage_filtered_t;

// A `/tp` of `player` from `before` to `after`. `cancelled` is true
// when a state filter refused it; the player then stays at `before`.
typedef struct tuff_plugin_types_teleport_attempt_t {
  tuff_plugin_types_player_t   player;
  plugin_string_t   before_dimension;
  tuff_plugin_types_vec3_t   before;
  plugin_string_t   after_dimension;
  tuff_plugin_types_vec3_t   after;
  bool   cancelled;
} tuff_plugin_types_teleport_attempt_t;

// A box the server watches for `watch-region`; players crossing its
// border are reported as `region-crossed`.
typedef struct tuff_plugin_types_region_watch_t {
  // Reported back in the events; unique per plugin.
  plugin_string_t   name;
  plugin_string_t   dimension;
  // Inclusive corners, in any order.
  tuff_plugin_types_block_pos_t   min;
  tuff_plugin_types_block_pos_t   max;
} tuff_plugin_types_region_watch_t;

// `player` entered (`entered`) or left the region named `region`.
// Moving to another dimension or logging out counts as leaving.
typedef struct tuff_plugin_types_region_crossed_t {
  tuff_plugin_types_player_t   player;
  plugin_string_t   region;
  bool   entered;
} tuff_plugin_types_region_crossed_t;

// A player who came back to life, standing at `pos` in `dimension`.
typedef struct tuff_plugin_types_respawned_t {
  tuff_plugin_types_player_t   player;
  tuff_plugin_types_vec3_t   pos;
  plugin_string_t   dimension;
} tuff_plugin_types_respawned_t;

typedef struct tuff_plugin_types_sneak_change_t {
  tuff_plugin_types_player_t   player;
  bool   sneaking;
} tuff_plugin_types_sneak_change_t;

// A game mode change from `before` to `after` (names such as `survival`).
// `cancelled` is true when a state filter refused it; the mode then
// stays `before`.
typedef struct tuff_plugin_types_game_mode_changed_t {
  tuff_plugin_types_player_t   player;
  plugin_string_t   before;
  plugin_string_t   after;
  bool   cancelled;
} tuff_plugin_types_game_mode_changed_t;

// A food level change. `locked` is true when a state filter undid a
// loss, so `after` is below the level the player kept.
typedef struct tuff_plugin_types_hunger_changed_t {
  tuff_plugin_types_player_t   player;
  int32_t   before;
  int32_t   after;
  bool   locked;
} tuff_plugin_types_hunger_changed_t;

typedef struct tuff_plugin_types_world_changed_t {
  tuff_plugin_types_player_t   player;
  plugin_string_t   before;
  plugin_string_t   after;
} tuff_plugin_types_world_changed_t;

// A change of player state.
typedef struct tuff_plugin_types_state_change_t {
  uint8_t tag;
  union {
    tuff_plugin_types_respawned_t     respawn;
    tuff_plugin_types_sneak_change_t     sneak;
    tuff_plugin_types_game_mode_changed_t     game_mode;
    tuff_plugin_types_hunger_changed_t     hunger;
    tuff_plugin_types_world_changed_t     dimension;
    tuff_plugin_types_teleport_attempt_t     teleport;
    tuff_plugin_types_region_crossed_t     region;
  } val;
} tuff_plugin_types_state_change_t;

#define TUFF_PLUGIN_TYPES_STATE_CHANGE_RESPAWN 0
#define TUFF_PLUGIN_TYPES_STATE_CHANGE_SNEAK 1
#define TUFF_PLUGIN_TYPES_STATE_CHANGE_GAME_MODE 2
#define TUFF_PLUGIN_TYPES_STATE_CHANGE_HUNGER 3
#define TUFF_PLUGIN_TYPES_STATE_CHANGE_DIMENSION 4
#define TUFF_PLUGIN_TYPES_STATE_CHANGE_TELEPORT 5
#define TUFF_PLUGIN_TYPES_STATE_CHANGE_REGION 6

typedef uint8_t tuff_plugin_types_state_kind_t;

// Refuses game mode changes into `game-mode`.
#define TUFF_PLUGIN_TYPES_STATE_KIND_GAME_MODE 0
// Undoes food level losses.
#define TUFF_PLUGIN_TYPES_STATE_KIND_HUNGER_LOSS 1
// Refuses `/tp` moves; `dimension` is where the player is going.
#define TUFF_PLUGIN_TYPES_STATE_KIND_TELEPORT 2

// Which player state changes the server refuses without running guest
// code. Every field that is set must match; matches are still
// reported as `game-mode-change` or `hunger-change` events.
typedef struct tuff_plugin_types_state_filter_t {
  tuff_plugin_types_state_kind_t   kind;
  // Only this player; none for any.
  tuff_plugin_types_option_uuid_t   player;
  // A dimension key the player must be in; none for any.
  plugin_option_string_t   dimension;
  // For `game-mode`: the target mode name; none for any.
  plugin_option_string_t   game_mode;
} tuff_plugin_types_state_filter_t;

typedef uint8_t tuff_plugin_types_menu_error_t;

// Rows outside 1 to 6, too many items, a slot outside the rows, an
// unknown item or bad SNBT.
#define TUFF_PLUGIN_TYPES_MENU_ERROR_INVALID 0
// The player is not online.
#define TUFF_PLUGIN_TYPES_MENU_ERROR_OFFLINE 1
// A text over its size limit, or too many menu calls in one call.
#define TUFF_PLUGIN_TYPES_MENU_ERROR_OVER_BUDGET 2
// The plugin lacks the `cap.player-write` grant.
#define TUFF_PLUGIN_TYPES_MENU_ERROR_NOT_GRANTED 3

// A use of the held item in the air the server cancelled; the
// player's eyes are at `acting-location`.
typedef struct tuff_plugin_types_item_use_t {
  tuff_plugin_types_player_t   player;
  // The held item's id.
  plugin_string_t   item;
  plugin_string_t   dimension;
  // Where they looked.
  tuff_plugin_types_rotation_t   rotation;
} tuff_plugin_types_item_use_t;

typedef struct {
  bool is_some;
  tuff_plugin_types_block_pos_t val;
} tuff_plugin_types_option_block_pos_t;

// What the projectile of the `projectile-hit` event being handled
// struck.
typedef struct tuff_plugin_types_hit_t {
  // The player or mob that shot or threw it.
  tuff_plugin_types_option_uuid_t   owner;
  // The block it struck; none when it struck an entity.
  tuff_plugin_types_option_block_pos_t   block;
  // The entity or player it struck, when known.
  tuff_plugin_types_option_uuid_t   target;
} tuff_plugin_types_hit_t;

// What hurt a player, for the `player-hurt` or `player-death` event
// being handled.
typedef struct tuff_plugin_types_damage_source_t {
  // The player or mob that dealt it: the melee attacker, or the
  // owner of the projectile or explosion.
  tuff_plugin_types_option_uuid_t   attacker;
  // The attacker's type, like `minecraft:player`.
  plugin_option_string_t   attacker_kind;
  // The type of the projectile that hit, if one did.
  plugin_option_string_t   projectile;
  // Who gets the kill: the last player to hurt them in the last 100
  // ticks, else the last mob, so a knock into the void still
  // credits the knocker.
  tuff_plugin_types_option_uuid_t   credit;
  bool   credit_is_player;
} tuff_plugin_types_damage_source_t;

// A box in which the server cancels players' breaks and placements
// and spares blocks from explosions, resending the blocks to the
// player.
typedef struct tuff_plugin_types_block_rule_t {
  plugin_string_t   dimension;
  // Inclusive corners, in any order.
  tuff_plugin_types_block_pos_t   min;
  tuff_plugin_types_block_pos_t   max;
  // Whether players may place blocks inside.
  bool   place;
  // Whether players may break blocks players placed inside after
  // the rule was added.
  bool   break_placed;
  // Block ids players may always break inside.
  plugin_list_string_t   breakable;
  // Whether explosions may destroy blocks players placed inside
  // after the rule was added; nothing else inside explodes.
  bool   explode_placed;
  // Block ids explosions never destroy inside, even placed ones.
  plugin_list_string_t   blast_proof;
  // Whether explosions centred inside are cancelled whole: no
  // damage, knockback, block loss, fire or sound.
  bool   cancel_explosions;
} tuff_plugin_types_block_rule_t;

// An explosion that found `blocks` blocks within reach, before any
// rule spared some.
typedef struct tuff_plugin_types_explosion_t {
  plugin_string_t   dimension;
  uint32_t   blocks;
  // The player who lit it, if any.
  tuff_plugin_types_option_uuid_t   igniter;
  tuff_plugin_types_vec3_t   center;
  double   radius;
} tuff_plugin_types_explosion_t;

// Something that happened, after the fact: no event can cancel what
// it reports.
typedef struct tuff_plugin_types_event_t {
  uint8_t tag;
  union {
    tuff_plugin_types_player_t     join;
    tuff_plugin_types_player_t     leave;
    tuff_plugin_types_chat_message_t     chat;
    tuff_plugin_types_block_change_t     block_break;
    tuff_plugin_types_block_change_t     block_place;
    tuff_plugin_types_click_t     left_click;
    tuff_plugin_types_click_t     right_click;
    tuff_plugin_types_entity_t     entity_spawn;
    tuff_plugin_types_entity_t     entity_death;
    tuff_plugin_types_entity_t     entity_damage;
    tuff_plugin_types_damage_t     player_hurt;
    tuff_plugin_types_death_t     player_death;
    tuff_plugin_types_inside_t     inside_block;
    tuff_plugin_types_config_change_t     config_change;
    tuff_plugin_types_login_attempt_t     login;
    tuff_plugin_types_menu_click_t     menu_click;
    tuff_plugin_types_menu_close_t     menu_close;
    tuff_plugin_types_entity_interact_t     entity_interact;
    tuff_plugin_types_item_use_t     use_item;
    tuff_plugin_types_entity_t     projectile_hit;
    tuff_plugin_types_player_attack_t     player_attack;
    tuff_plugin_types_damage_filtered_t     damage_filtered;
    tuff_plugin_types_item_action_t     item_drop;
    tuff_plugin_types_item_action_t     item_pickup;
    tuff_plugin_types_item_action_t     item_swap;
    tuff_plugin_types_item_action_t     item_craft;
    tuff_plugin_types_items_taken_t     items_taken;
    tuff_plugin_types_explosion_t     explosion;
    tuff_plugin_types_inventory_click_t     inventory_click;
    tuff_plugin_types_inventory_window_t     inventory_open;
    tuff_plugin_types_inventory_window_t     inventory_close;
    tuff_plugin_types_state_change_t     player_state;
    tuff_plugin_types_payload_message_t     payload;
  } val;
} tuff_plugin_types_event_t;

