// Imported Functions from `tuff:plugin/host@0.1.0`
extern void tuff_plugin_host_log(tuff_plugin_host_log_level_t level, plugin_string_t *message);
// Claims a command; its root may start with one `/` (`//set`).
extern bool tuff_plugin_host_register_command(tuff_plugin_host_command_tree_t *tree, tuff_plugin_host_register_error_t *err);
// Claims `/tuff <name>`, the tree's root.
extern bool tuff_plugin_host_register_tuff_subcommand(tuff_plugin_host_command_tree_t *tree, tuff_plugin_host_register_error_t *err);
// `/name ...` runs as `target ...`, a command or `tuff <sub>` the
// plugin owns, at most four words.
extern bool tuff_plugin_host_register_alias(plugin_string_t *name, plugin_string_t *target, tuff_plugin_host_register_error_t *err);
extern bool tuff_plugin_host_subscribe(tuff_plugin_host_event_kinds_t kinds, tuff_plugin_host_register_error_t *err);
extern bool tuff_plugin_host_intercept_click(tuff_plugin_host_click_filter_t *filter, tuff_plugin_host_register_error_t *err);
// Register phase: receives client custom payloads on `channel`
// (`namespace:path`, not `minecraft:`) as `payload` events and may
// send on it with `send-payload`. At most 16 channels per plugin.
extern bool tuff_plugin_host_register_channel(plugin_string_t *channel, tuff_plugin_host_register_error_t *err);
// Sends a custom payload packet (at most 32767 bytes) on a channel
// the plugin registered to an online player.
extern bool tuff_plugin_host_send_payload(tuff_plugin_host_uuid_t *player, plugin_string_t *channel, plugin_list_u8_t *data, tuff_plugin_host_host_error_t *err);
// Cancels the item actions `filter` matches and reports them as events.
extern bool tuff_plugin_host_intercept_item(tuff_plugin_host_item_filter_t *filter, tuff_plugin_host_register_error_t *err);
// Cancels the window clicks `filter` matches and reports every
// click as an `inventory-click` event.
extern bool tuff_plugin_host_intercept_inventory(tuff_plugin_host_inventory_filter_t *filter, tuff_plugin_host_register_error_t *err);
// Reports players and entities inside blocks of this id (a block
// name like `minecraft:end_gateway`) as `inside-block` events, and
// makes the server treat those blocks as the plugin's portals: the
// vanilla behaviour of a plain block of that id does not run, and no
// advancement fires for entering it. Subscribes to `inside-block`.
extern bool tuff_plugin_host_watch_block(plugin_string_t *block, tuff_plugin_host_register_error_t *err);
// Reports players entering and leaving the box as `player-state`
// events of the `region` case, tracked by the server each tick. At
// most 16 per plugin; a duplicate name is invalid. Subscribes to
// `player-state`.
extern bool tuff_plugin_host_watch_region(tuff_plugin_host_region_watch_t *region, tuff_plugin_host_register_error_t *err);
// Declares a node `<plugin id>.<rest>`. Level 0: every player holds
// it unless denied; 1 to 4: operators at that level or above hold it
// without a grant.
extern bool tuff_plugin_host_declare_permission(plugin_string_t *node, uint8_t level, tuff_plugin_host_register_error_t *err);
// Declares a setting; reports changes as `config-change` events once
// the plugin subscribes to them.
extern bool tuff_plugin_host_declare_config(tuff_plugin_host_config_decl_t *decl, tuff_plugin_host_register_error_t *err);
// Offers a resource pack while the plugin is loaded; the archive is
// checked here.
extern bool tuff_plugin_host_register_resource_pack(tuff_plugin_host_resource_pack_t *pack, tuff_plugin_host_register_error_t *err);
// Adds a page to the web admin panel while the plugin is loaded.
extern bool tuff_plugin_host_register_panel_page(tuff_plugin_host_panel_page_t *page, tuff_plugin_host_register_error_t *err);
// Mounts a panel API while the plugin is loaded.
extern bool tuff_plugin_host_register_panel_api(tuff_plugin_host_panel_api_t *api, tuff_plugin_host_register_error_t *err);
// Adds a dashboard card while the plugin is loaded.
extern bool tuff_plugin_host_register_panel_card(tuff_plugin_host_panel_card_t *card, tuff_plugin_host_register_error_t *err);
// Sets the value of a registered card's series.
extern bool tuff_plugin_host_panel_card_set(plugin_string_t *series, int64_t value, tuff_plugin_host_host_error_t *err);
// Refuses the login a `login` event reports, with `reason` shown to
// the player. Only valid while handling that event.
extern bool tuff_plugin_host_refuse_login(plugin_string_t *reason, tuff_plugin_host_host_error_t *err);
// Messages the player the current call acts for.
extern bool tuff_plugin_host_reply(plugin_string_t *message, tuff_plugin_host_host_error_t *err);
extern bool tuff_plugin_host_broadcast(plugin_string_t *message, tuff_plugin_host_host_error_t *err);
// Messages an online player.
extern bool tuff_plugin_host_tell(tuff_plugin_host_uuid_t *player, plugin_string_t *message, tuff_plugin_host_host_error_t *err);
// Messages an online player with styled spans that may carry click
// and hover events: at most 32 spans, each text, hover, insertion
// and click value at most 256 bytes. Counts against the message limit.
extern bool tuff_plugin_host_tell_rich(tuff_plugin_host_uuid_t *player, tuff_plugin_host_list_rich_span_t *spans, tuff_plugin_host_host_error_t *err);
// Queues a title and subtitle for an online player (legacy `\u{a7}`
// codes style them, as in messages); times are in ticks. Either text
// may be empty.
extern bool tuff_plugin_host_show_title(tuff_plugin_host_uuid_t *player, tuff_plugin_host_title_spec_t *title, tuff_plugin_host_host_error_t *err);
// Queues clearing and resetting a player's title.
extern bool tuff_plugin_host_clear_title(tuff_plugin_host_uuid_t *player, tuff_plugin_host_host_error_t *err);
// Queues action bar text for an online player.
extern bool tuff_plugin_host_action_bar(tuff_plugin_host_uuid_t *player, plugin_string_t *text, tuff_plugin_host_host_error_t *err);
// Shows the plugin's own sidebar to everyone (one shared objective
// per plugin, replacing its last one): `title` and up to 15 `lines`,
// the first on top, without numbers. Another plugin's or a command's
// sidebar is replaced while this one is shown; it goes away on
// `sidebar-clear` or unload.
extern bool tuff_plugin_host_sidebar_set(plugin_string_t *title, plugin_list_string_t *lines, tuff_plugin_host_host_error_t *err);
extern bool tuff_plugin_host_sidebar_clear(tuff_plugin_host_host_error_t *err);
// Creates or updates scoreboard team `<plugin id>.<name>`: a
// `color` (a chat color name such as `red`; tints names and the
// tab list), a `prefix` and `suffix` around members' names, and
// exactly these `members` (player names). Teams go away on
// `team-remove` or unload.
extern bool tuff_plugin_host_team_set(plugin_string_t *name, tuff_plugin_host_team_spec_t *team, tuff_plugin_host_host_error_t *err);
extern bool tuff_plugin_host_team_remove(plugin_string_t *name, tuff_plugin_host_host_error_t *err);
// Declares that this plugin serves `interface` with these method keys
// (register phase; at most 32 interfaces; several plugins may provide
// one interface).
extern bool tuff_plugin_host_provide(plugin_string_t *interface, plugin_list_u64_t *methods, tuff_plugin_host_register_error_t *err);
// Sends a request to the provider of `interface` (`target` none = the
// sole provider). The outcome arrives as an `io-event` reply carrying
// the returned handle. `timeout-ticks` 0 means 100; the maximum is 6000.
extern bool tuff_plugin_host_request(plugin_string_t *maybe_target, plugin_string_t *interface, uint64_t method, plugin_list_u8_t *payload, uint32_t timeout_ticks, tuff_plugin_host_handle_t *ret, tuff_plugin_host_call_error_t *err);
// One-way message (`target` none = every provider); returns how many
// deliveries were queued.
extern bool tuff_plugin_host_notify(plugin_string_t *maybe_target, plugin_string_t *interface, uint64_t method, plugin_list_u8_t *payload, uint32_t *ret, tuff_plugin_host_call_error_t *err);
// Answers a request delivered earlier; any later call may do so.
extern bool tuff_plugin_host_respond(uint64_t request, tuff_plugin_host_result_list_u8_string_t *outcome, tuff_plugin_host_host_error_t *err);
// The version of a loaded plugin.
extern bool tuff_plugin_host_plugin_loaded(plugin_string_t *id, plugin_string_t *ret);
// Runs `on-timer(token)` after `delay` server ticks.
